# Let's take the changed pairs and analyze minimal edits
inputs = ['ck', 'ccwg', 'du', 'wk', 'gz']
outputs = ['a', 'cckg', 'dd', 'kkjj', 'ggj']

# Analyze each change:
print("Analyzing each transformation:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {outp}")
    if len(inp) == len(outp):
        # Same length, character substitution
        for j, (char_in, char_out) in enumerate(zip(inp, outp)):
            if char_in != char_out:
                print(f"  Position {j}: '{char_in}' -> '{char_out}'")
    elif len(inp) > len(outp):
        # Characters removed
        print(f"  Characters removed: {len(inp) - len(outp)}")
    else:
        # Characters added
        print(f"  Characters added: {len(outp) - len(inp)}")
    print()

